function howItWorksV3(){return `<div class="apple-page"><section class="apple-hero"><span class="eyebrow">Cómo funciona</span><h1>De un documento creado con IA a una revisión que puedes explicar.</h1><p>HumINT prepara el alcance, coordina a las personas revisoras y conserva las conclusiones y firmas de una versión concreta.</p></section><div class="how-steps"><article class="how-step"><span class="num">01</span><h2>Define el encargo.</h2><p>Sube el documento, explica para qué se utilizará y señala qué perfiles expertos crees necesarios. Puedes trabajar con tu equipo, un profesional de confianza o solicitar ayuda externa.</p></article><article class="how-step"><span class="num">02</span><h2>Prepara la revisión.</h2><p>La IA propone comprobaciones, relaciona cada punto con las especialidades adecuadas y señala información pendiente. La propuesta queda claramente identificada y requiere confirmación humana.</p></article><article class="how-step"><span class="num">03</span><h2>Revisa con evidencia.</h2><p>Cada persona consulta el documento y las fuentes necesarias, registra su propia conclusión y solicita cambios cuando hacen falta. Nadie puede decidir ni firmar por otra persona.</p></article><article class="how-step"><span class="num">04</span><h2>Firma una versión.</h2><p>Las declaraciones se envían al proveedor de firma y quedan vinculadas a una versión concreta. Una versión nueva necesita sus propias confirmaciones.</p></article><article class="how-step"><span class="num">05</span><h2>Comparte el resultado.</h2><p>El informe y el sello muestran únicamente la información autorizada: alcance, resultado, personas firmantes y estado de la comprobación técnica.</p></article></div><section class="how-callout"><span class="eyebrow light">La regla central</span><h2>La IA propone. Las personas deciden.</h2><p>HumINT no sustituye el juicio profesional, no firma por nadie y no presenta el sello como una certificación administrativa.</p><a data-nav href="/empezar-revision" class="button secondary">Empezar revisión</a></section></div>`}

function pricesV3(){return `<div class="apple-page"><section class="apple-hero"><span class="eyebrow">Precios</span><h1>Una suscripción para coordinar todas tus revisiones.</h1><p>La empresa contrata HumINT. Las personas invitadas pueden revisar los encargos a los que tengan acceso sin comprar otra suscripción.</p></section><div class="pricing-v3"><div class="billing-toggle" role="group" aria-label="Periodicidad"><button class="active" data-billing="monthly">Mensual</button><button data-billing="annual">Anual</button></div><section class="pricing-card-v3"><div><span class="eyebrow">Plan Empresa</span><h2>HumINT</h2><p class="billing-period">Facturación mensual</p><div class="pricing-placeholder"><b>Precio pendiente de configuración</b><br><small>No se mostrará ningún importe hasta que esté conectado con la tarifa real.</small></div><a data-nav href="/empezar-revision" class="button">Empezar revisión</a><p class="form-note">Los honorarios de expertos externos y costes adicionales de firma se muestran antes de contratar.</p></div><ul class="pricing-list-v3"><li>Checklist preparada con ayuda de IA</li><li>Uno o varios expertos asignados a cada punto</li><li>Revisión interna, por invitación y autorrevisión</li><li>Versiones, conclusiones y evidencias</li><li>Firma mediante proveedor integrado</li><li>Informe y verificación del sello HumINT</li><li>Invitados sin suscripción propia</li></ul></section></div></div>`}

function startReviewV3(){return `<div class="apple-page"><section class="apple-hero"><span class="eyebrow">Empezar revisión</span><h1>Prepara tu primera revisión.</h1><p>Para procesar un documento necesitas iniciar sesión y disponer de una suscripción activa. Puedes guardar el borrador antes de contratar.</p></section><div class="review-gate"><section class="gate-card"><div class="gate-step"><span class="num">01</span><div><b>Inicia sesión o crea una cuenta</b><small>Conservaremos el destino para que vuelvas directamente a tu revisión.</small></div><span class="gate-status">Necesario</span></div><div class="gate-step"><span class="num">02</span><div><b>Activa una suscripción</b><small>Verás el precio, la periodicidad y cualquier coste adicional antes del pago.</small></div><span class="gate-status">Necesario</span></div><div class="gate-step"><span class="num">03</span><div><b>Sube el documento</b><small>Define su finalidad, el alcance y los perfiles que deben participar.</small></div><span class="gate-status">Siguiente</span></div><a data-nav href="/acceso?modo=registro&destino=/app/revisiones/nueva" class="button">Iniciar sesión para continuar</a><p class="form-note">Entorno de demostración: no se realizará ningún cargo ni se enviará ningún documento a terceros.</p></section></div></div>`}

function accessV3(){const params=new URLSearchParams(location.search),reg=params.get('modo')==='registro'||state.auth==='register',review=params.get('destino')?.includes('revisiones');return `<div class="auth-wrap"><section class="auth-card"><a data-nav href="/" class="wordmark-link"><img class="wordmark-img" src="/assets/humint-wordmark-v2.png" alt="HumINT"></a><div class="auth-tabs"><button class="auth-tab ${!reg?'active':''}" data-auth="login">Entrar</button><button class="auth-tab ${reg?'active':''}" data-auth="register">Crear cuenta</button></div><h1>${reg?'Crea tu cuenta':'Entra en HumINT'}</h1><p>${review?'Accede para preparar tu revisión. Después comprobaremos que tu espacio tenga una suscripción activa.':reg?'Organiza la revisión humana de tus documentos desde un mismo lugar.':'Accede a tus documentos y a las revisiones en las que participas.'}</p><label class="field"><span>Correo electrónico</span><input type="email" placeholder="nombre@empresa.com"></label>${reg?`<label class="check"><input type="checkbox"> <span>He leído y acepto las <a data-nav href="/condiciones"><u>condiciones del servicio</u></a>. Consulta el tratamiento de datos en la <a data-nav href="/privacidad"><u>política de privacidad</u></a>.</span></label>`:''}<button class="button full" data-demo-login>${reg?'Crear cuenta y continuar':'Enviar enlace de acceso'}</button><p class="form-note">${reg?'En esta demostración no se enviará ningún mensaje.':'Recibirás un enlace para acceder a tu cuenta.'}</p></section></div>`}

function clampV3(n,a=0,b=1){return Math.max(a,Math.min(b,n))}
